/* Dependency-free 3D mesh renderer: perspective-projected terracotta bowl, painter-sorted faces, interactive rotation. */
(()=>{'use strict';const canvas=document.getElementById('diya-canvas'),ctx=canvas.getContext('2d');if(!ctx)return;let yaw=-.2,pitch=.58,lit=false,drag=false,lastX=0,lastY=0,visible=true;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const N=64,mesh=[];
function point(r,a,y){const taper=1+.2*Math.cos(a);return[Math.cos(a)*r*taper,y,Math.sin(a)*r*.78]}
for(let i=0;i<N;i++){const a=i/N*Math.PI*2,b=(i+1)/N*Math.PI*2;mesh.push({v:[point(1,a,0),point(1,b,0),point(.57,b,-.40),point(.57,a,-.40)],type:'outer'});mesh.push({v:[point(.92,a,.01),point(.92,b,.01),point(.48,b,-.25),point(.48,a,-.25)],type:'inner'});mesh.push({v:[point(1,a,0),point(1,b,0),point(.92,b,.01),point(.92,a,.01)],type:'rim'})}
function rotate(v){const x=v[0]*Math.cos(yaw)-v[2]*Math.sin(yaw),z=v[0]*Math.sin(yaw)+v[2]*Math.cos(yaw);return[x,v[1]*Math.cos(pitch)-z*Math.sin(pitch),v[1]*Math.sin(pitch)+z*Math.cos(pitch)]}
function project(v){const q=rotate(v),scale=170/(1+q[2]*.16);return[320+q[0]*scale,278-q[1]*scale,q[2]]}
function path(points){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath()}
function draw(t=0){const dpr=Math.min(devicePixelRatio||1,2),w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(canvas.width/640,0,0,canvas.height/520,0,0);ctx.clearRect(0,0,640,520);
const shadow=ctx.createRadialGradient(320,374,5,320,374,175);shadow.addColorStop(0,'rgba(92,52,27,.2)');shadow.addColorStop(1,'rgba(92,52,27,0)');ctx.save();ctx.translate(0,205);ctx.scale(1,.45);ctx.fillStyle=shadow;ctx.fillRect(100,220,450,300);ctx.restore();
if(lit){const glow=ctx.createRadialGradient(320,212,0,320,212,205);glow.addColorStop(0,'rgba(251,183,49,.22)');glow.addColorStop(1,'rgba(251,183,49,0)');ctx.fillStyle=glow;ctx.fillRect(90,10,460,430)}
const faces=mesh.map(f=>{const v=f.v.map(project);return{...f,v,depth:v.reduce((a,p)=>a+p[2],0)/v.length}}).sort((a,b)=>b.depth-a.depth);for(const f of faces){path(f.v);const shade=Math.round(41-f.depth*13);ctx.fillStyle=f.type==='rim'?`hsl(28,58%,${shade+17}%)`:f.type==='inner'?`hsl(24,55%,${shade-10}%)`:`hsl(23,55%,${shade}%)`;ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.7;ctx.stroke()}
// Decorative dotted band sits on the curved lip of the three dimensional bowl.
for(let i=0;i<48;i++){const p=project(point(.965,i/48*Math.PI*2,.015));ctx.beginPath();ctx.arc(p[0],p[1],2,0,Math.PI*2);ctx.fillStyle='#e8b871';ctx.fill()}
const wick=project([.38,.035,0]);ctx.beginPath();ctx.moveTo(wick[0]-8,wick[1]+2);ctx.quadraticCurveTo(wick[0],wick[1]-9,wick[0]+3,wick[1]-16);ctx.strokeStyle='#dfc391';ctx.lineWidth=5;ctx.stroke();if(lit){const flicker=reduced?0:Math.sin(t*.004)*4;const x=wick[0]+3,y=wick[1]-15;ctx.save();ctx.shadowColor='#ffc64e';ctx.shadowBlur=27;const g=ctx.createLinearGradient(x,y-85,x,y);g.addColorStop(0,'#fff5b9');g.addColorStop(.45,'#ffdc65');g.addColorStop(1,'#f6902b');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(x,y);ctx.bezierCurveTo(x-28,y-23,x-7+flicker,y-60,x+flicker,y-86);ctx.bezierCurveTo(x+27,y-44,x+29,y-9,x,y);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff7cb';ctx.beginPath();ctx.moveTo(x,y-4);ctx.quadraticCurveTo(x-14,y-19,x+2,y-49);ctx.quadraticCurveTo(x+16,y-12,x,y-4);ctx.fill();ctx.restore();if(!reduced){for(let i=0;i<7;i++){const phase=(t*.00013+i*.14)%1;ctx.globalAlpha=(1-phase)*.5;ctx.fillStyle='#c89437';ctx.beginPath();ctx.arc(x+Math.sin(i*3+phase*5)*55,y-phase*150,1.5,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}}}
let raf;function animate(t){if(visible){draw(t);if(lit&&!reduced)raf=requestAnimationFrame(animate)}}function update(){cancelAnimationFrame(raf);raf=requestAnimationFrame(animate)}
canvas.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-lastX)*.01;pitch=Math.max(.24,Math.min(1.05,pitch+(e.clientY-lastY)*.005));lastX=e.clientX;lastY=e.clientY;update()});canvas.addEventListener('pointerup',()=>drag=false);canvas.addEventListener('pointercancel',()=>drag=false);
document.getElementById('light-diya').onclick=()=>{lit=!lit;document.getElementById('light-diya').innerHTML=lit?'✧ Your diya is glowing · Light again':'✧ Make a wish & light the diya';document.getElementById('diya-message').textContent=lit?'May your days be bright, and your heart be light. Happy Diwali!':'Your own little moment of celebration.';update()};window.addEventListener('resize',update);if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)update();else cancelAnimationFrame(raf)}).observe(canvas);update()})();
